import { getBounty, getLeaderboard, getProfile } from './api.js';
import { esc, money, number, date, shortDate, timeLeft, accepting, bountyURL, profileURL, markdown, avatar, pageNumber } from './format.js';
import { statusBadge, saveButton, categoryIcon } from './views.js';

function tabs(b, active) {
  return `<nav class="detail-tabs" aria-label="Bounty pages"><a href="${bountyURL(b.slug)}" ${active === 'overview' ? 'aria-current="page"' : ''}>Overview</a><a href="${bountyURL(b.slug)}/leaderboard" ${active === 'leaderboard' ? 'aria-current="page"' : ''}>Leaderboard <span>${number(b.submissionCount)}</span></a><a href="${bountyURL(b.slug)}/rules" ${active === 'rules' ? 'aria-current="page"' : ''}>Rules & requirements</a></nav>`;
}
function heading(b, active) {
  return `<a href="#/" class="back-link">← All bounties</a><div class="bounty-heading"><div class="category-icon large-icon tone-${esc((b.category || '').toLowerCase())}" aria-hidden="true">${categoryIcon(b.category)}</div><div><div class="detail-kicker">${esc(b.category)} <span>·</span> by ${esc(b.sponsor?.name || 'make.fun')} <span class="verified">✦</span></div><h1>${esc(b.title)}</h1><div class="detail-badges">${statusBadge(b)}<span class="muted">${number(b.submissionCount)} entries</span></div></div>${saveButton(b)}</div><p class="detail-summary">${esc(b.summary)}</p>${tabs(b, active)}`;
}
function rewards(b) {
  const rows = b.rewardsNow?.length ? b.rewardsNow : Object.entries(b.rewards || {}).map(([place, amountUsd]) => ({ place, amountUsd, baseUsd: amountUsd, feeShareUsd: 0 }));
  return `<section class="panel reward-panel"><div class="panel-heading"><h2>Prize breakdown</h2><span>USDC</span></div><table class="rewards-table"><caption class="sr-only">Current rewards including entry fee shares</caption><thead><tr><th>Place</th><th>Base</th><th>Fee share</th><th>Total</th></tr></thead><tbody>${rows.map(r => `<tr><td><span class="place ${Number(r.place) <= 3 ? `place-${r.place}` : ''}">${r.place <= 3 ? ['①', '②', '③'][r.place - 1] : '#' + esc(r.place)}</span> ${r.place <= 3 ? ['First', 'Second', 'Third'][r.place - 1] : 'Place ' + esc(r.place)}</td><td>${money(r.baseUsd)}</td><td>${money(r.feeShareUsd)}</td><td>${money(r.amountUsd)}</td></tr>`).join('') || '<tr><td colspan="4">Rewards will be announced.</td></tr>'}</tbody></table><p class="table-note">Live rewards include entry fees collected so far. Final awards follow the bounty’s rules.</p></section>`;
}
function sidebar(b) {
  return `<aside class="detail-sidebar"><section class="panel prize-panel"><span class="eyebrow">LIVE PRIZE POOL</span><div class="detail-pot">${money(b.potUsd ?? b.rewardAmount)}<span>USDC</span></div><p>Build something great. Earn your share.</p><div class="prize-facts"><div><span>Entry fee</span><strong>${Number(b.entryFeeUsd) ? money(b.entryFeeUsd) + ' USDC' : 'Free entry'}</strong></div><div><span>Time remaining</span><strong class="${accepting(b) ? 'purple' : ''}" data-deadline="${esc(b.deadline)}">${timeLeft(b.deadline)}</strong></div><div><span>Total entries</span><strong>${number(b.submissionCount)}</strong></div><div><span>Base reward</span><strong>${money(b.rewardAmount)}</strong></div>${Number(b.entryFeesUsd) ? `<div><span>Fees added to pot</span><strong>+${money(b.entryFeesUsd)}</strong></div>` : ''}</div><a class="primary-button full-width" href="https://make.fun/bounty/${encodeURIComponent(b.slug)}">${accepting(b) ? 'Explore entry instructions' : 'View on make.fun'} <span aria-hidden="true">↗</span></a><span class="prize-footnote">${accepting(b) ? 'Enter and manage your submission on make.fun' : 'This bounty is no longer taking entries'}</span></section><section class="panel timeline"><h2>Mark your calendar</h2><div><i></i><span>Entries open<strong>${date(b.opensAt || b.publishedAt)}</strong></span></div><div><i></i><span>Submission deadline<strong>${date(b.deadline)}</strong></span></div>${(b.phases || []).filter(p => p.key !== 'dev').map(p => `<div><i></i><span>${esc(p.title)} starts<strong>${date(p.startsAt)}</strong></span></div>`).join('')}${b.resolvedAt ? `<div><i></i><span>Results published<strong>${date(b.resolvedAt)}</strong></span></div>` : ''}</section><section class="sidebar-tip"><span aria-hidden="true">✧</span><div><strong>A fair shot for every builder.</strong><p>Entries are scored and ranked in the open. Read the rules before you build.</p></div></section></aside>`;
