export async function bountyPage(slug, active = 'overview') {
  const b = await getBounty(slug);
  const body = active === 'rules' ? `<section class="panel prose"><div class="section-eyebrow">KNOW THE CHALLENGE</div><h2>Rules & requirements</h2>${markdown(typeof b.rules === 'string' ? b.rules : JSON.stringify(b.rules || 'See the official bounty for its full rules.', null, 2))}${b.rulesNote ? `<p>${esc(b.rulesNote)}</p>` : ''}</section>` : `<section class="panel prose"><div class="section-eyebrow">THE CHALLENGE</div><h2>Make your next great thing.</h2>${markdown(b.description)}</section>${b.resolution?.summary ? `<section class="panel prose"><h2>How entries are judged</h2><p>${esc(b.resolution.summary)}</p>${b.resolution.criteria?.length ? `<details><summary>Scoring criteria</summary><ul>${b.resolution.criteria.map(c => `<li>${esc(c)}</li>`).join('')}</ul></details>` : ''}</section>` : ''}${rewards(b)}<section class="panel prose"><h2>Ready to take on the challenge?</h2><p>Get to know the field, check the full requirements, and start making.</p><div class="button-row"><a class="secondary-button" href="${bountyURL(b.slug)}/leaderboard">Explore leaderboard →</a><a class="text-link" href="${bountyURL(b.slug)}/rules">Read the rules →</a></div></section>`;
  return { title: b.title, crumb: active === 'rules' ? 'Bounty rules' : 'Bounty overview', html: `${heading(b, active)}<div class="detail-layout"><div class="detail-main">${body}</div>${sidebar(b)}</div>` };
}

function scoreCell(row, data) {
  const raw = row.values?.[data.rank_key] ?? row.rank_value;
  if (raw == null) return esc(row.rank_display ?? '—');
  return data.rank_key === 'judge' ? `${(Number(raw) / 10000).toFixed(4)}%` : esc(row.display?.[data.rank_key] ?? row.rank_display ?? number(raw));
}
function leaderboardRows(rows, data) {
  return rows.map(r => `<tr><td class="rank-cell ${Number(r.rank) <= 3 ? 'purple' : ''}">${esc(r.rank ?? '—')}</td><td><div class="builder-cell">${avatar(r.handle, r.image)}<div><a class="builder-name" href="${profileURL(r.handle)}">${esc(r.handle)}</a>${r.house || r.baseline ? '<span class="house-tag">House</span>' : ''}<span class="entry-title">${esc(r.title || 'Untitled entry')}</span></div></div></td><td class="score-cell">${scoreCell(r, data)}${r.interval && data.rank_key === 'judge' ? `<small title="90% confidence interval">${(Number(r.interval.low) / 10000).toFixed(4)}–${(Number(r.interval.high) / 10000).toFixed(4)}%</small>` : ''}</td><td class="record-cell">${r.judge ? `${esc(r.judge.wins)} <span>W</span> · ${esc(r.judge.losses)} <span>L</span>` : r.prize_rank ? '#' + esc(r.prize_rank) : '—'}</td><td class="received-cell">${r.received_at ? shortDate(r.received_at) : '—'}</td></tr>`).join('');
}
export async function leaderboardPage(slug, params) {
  const [b, data] = await Promise.all([getBounty(slug), getLeaderboard(slug, params.get('phase') || '', params.get('view') || '')]);
  const all = [...(data.entries || []), ...(data.rest || [])];
  const query = (params.get('q') || '').toLowerCase();
  const filtered = all.filter(r => !query || `${r.handle} ${r.title}`.toLowerCase().includes(query));
  const pages = Math.max(1, Math.ceil(filtered.length / 25));
  const page = Math.min(pages, pageNumber(params.get('page')));
  const rows = filtered.slice((page - 1) * 25, page * 25);
  const rankTitle = data.rank_key === 'judge' ? 'Win rate' : data.columns?.find(c => c.key === data.rank_key)?.title || 'Score';
  return { title: `${b.title} · Leaderboard`, crumb: 'Leaderboard', html: `${heading(b, 'leaderboard')}<section class="panel leaderboard-panel"><div class="leaderboard-heading"><div><div class="section-eyebrow">THE BUILDERS SETTING THE PACE</div><h2>Leaderboard <span class="count-pill">${number(all.length)}</span></h2><p>${data.phase?.placements_held && !data.phase?.finalized_at ? 'Provisional standings. Final places follow the published results.' : 'Public standings, ranked by the bounty’s scoring rules.'}</p></div><label class="phase-control"><span class="sr-only">Leaderboard phase</span><select id="leaderboard-phase">${(b.phases || []).map(p => `<option value="${esc(p.key)}" ${p.key === data.phase?.key ? 'selected' : ''}>${esc(p.title)}</option>`).join('')}</select></label></div><div class="leaderboard-tools"><label class="search-box"><span aria-hidden="true">⌕</span><input type="search" id="leaderboard-search" placeholder="Find an entry or builder…" aria-label="Search leaderboard" value="${esc(params.get('q') || '')}"></label><span class="badge green"><i></i>${esc(data.phase?.title || 'Live')} standings</span></div>${data.phase?.scores_visible === false ? `<div class="empty-state"><span aria-hidden="true">◷</span><h3>Good things take a little time.</h3><p>Scores for this phase are held until the results are published.</p></div>` : rows.length ? `<div class="table-scroll"><table class="leaderboard-table"><caption class="sr-only">${esc(b.title)} standings</caption><thead><tr><th scope="col">Rank</th><th scope="col">Builder / entry</th><th scope="col">${esc(rankTitle)} ↓</th><th scope="col">${data.rank_key === 'judge' ? 'Record' : 'Prize place'}</th><th scope="col">Submitted</th></tr></thead><tbody>${leaderboardRows(rows, data)}</tbody></table></div>` : `<div class="empty-state"><h3>${query ? 'No matching entries' : 'The field is wide open.'}</h3><p>${query ? 'Try another name or entry title.' : 'Entries will appear here once their results are available.'}</p></div>`}<div class="leaderboard-footer"><span>${number(filtered.length)} entries ${data.rank_key === 'judge' ? '· Intervals show 90% confidence' : ''}</span>${pages > 1 ? `<div class="pager"><button data-page="${page - 1}" ${page === 1 ? 'disabled' : ''}>← Previous</button><span>${page} / ${pages}</span><button data-page="${page + 1}" ${page === pages ? 'disabled' : ''}>Next →</button></div>` : ''}</div></section>` };
}

